_CZ_FONT_REGULAR_B64 = ""
_CZ_FONT_BOLD_B64 = ""
_CZ_FONT_LATIN_B64 = ""




def iso_utc(value: datetime) -> str:
    return value.astimezone(ZoneInfo("UTC")).isoformat().replace("+00:00", "Z")


def request_json(url: str) -> Dict[str, Any]:
    request = Request(
        url,
        headers={
            "Accept": "application/json",
            "User-Agent": "PagerMaid-Codex-Reset/1.0",
        },
    )
    try:
        with urlopen(request, timeout=REQUEST_TIMEOUT) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        if exc.code == 429:
            raise RuntimeError("请求过于频繁，请稍后再试。") from exc
        raise RuntimeError(f"接口请求失败：HTTP {exc.code}") from exc
    except URLError as exc:
        raise RuntimeError(f"网络连接失败：{exc.reason}") from exc
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("接口返回的数据格式不正确。") from exc

    if not isinstance(payload, dict):
        raise RuntimeError("接口返回的数据格式不正确。")
    return payload


async def fetch_resets(start: datetime, end: datetime) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    cursor = ""
    seen_ids = set()
    seen_cursors = set()

    while True:
        params = {
            "limit": 100,
            "order": "desc",
            "from": iso_utc(start),
            "to": iso_utc(end),
        }
        if cursor:
            params["cursor"] = cursor

        payload = await asyncio.to_thread(
            request_json,
            f"{API_URL}?{urlencode(params)}",
        )
        page = payload.get("data")
        if not isinstance(page, list):
            raise RuntimeError("接口没有返回重置记录。")

        for item in page:
            if not isinstance(item, dict):
                continue
            record_id = str(item.get("id") or "")
            if record_id and record_id in seen_ids:
                continue
            if record_id:
                seen_ids.add(record_id)
            records.append(item)

        pagination = payload.get("pagination")
        if not isinstance(pagination, dict) or not pagination.get("has_more"):
            break
        cursor = str(pagination.get("next_cursor") or "")
        if not cursor:
            raise RuntimeError("接口分页信息不完整，请稍后重试。")
        if cursor in seen_cursors:
            raise RuntimeError("接口返回重复分页，请稍后重试。")
        seen_cursors.add(cursor)

    return records


def parse_announcement_time(value: Any) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        return parsed.astimezone(TIME_ZONE) if parsed.tzinfo is not None else None
    except (TypeError, ValueError):
        return None








_CZ_FONT_MONO_B64 = ""


def create_month_card(rows, now, total, page=1, pages=1):
    from PIL import Image, ImageDraw, ImageFilter, ImageFont

    font_data = {"regular": _CZ_FONT_REGULAR_B64, "bold": _CZ_FONT_BOLD_B64, "latin": _CZ_FONT_LATIN_B64}
    fonts = {(kind, size): ImageFont.truetype(io.BytesIO(base64.b64decode(data)), size)
             for kind, data in font_data.items() for size in (24, 28, 32, 34, 50, 52)}
    time_font = ImageFont.truetype(io.BytesIO(base64.b64decode(_CZ_FONT_MONO_B64)), 32)
    width, height = 1200, 349 + max(1, len(rows)) * 66
    image = Image.new("RGBA", (width, height), "#05070d")
    ambient = Image.new("RGBA", image.size, (0, 0, 0, 0))
    glow = ImageDraw.Draw(ambient)
    glow.ellipse((760, -260, 1360, 330), fill=(36, 211, 238, 42))
    glow.ellipse((-220, height - 280, 360, height + 220), fill=(139, 92, 246, 34))
    image = Image.alpha_composite(image, ambient.filter(ImageFilter.GaussianBlur(120)))
    draw = ImageDraw.Draw(image)

    def runs(value, size, bold):
        for part in re.findall(r"[\x00-\x7f]+|[^\x00-\x7f]+", value):
            kind = ("latin" if part.isascii() else "bold") if bold else "regular"
            yield part, fonts[kind, size]

    def measure(value, size, bold=True):
        return sum(draw.textlength(part, font=font) for part, font in runs(value, size, bold))

    def text(x, baseline, value, size=32, color="#f8fafc", bold=True):
        for part, font in runs(value, size, bold):
            draw.text((x, baseline), part, font=font, fill=color, anchor="ls")
            x += draw.textlength(part, font=font)

    text(55, 80, "Codex", 50)
    text(55 + measure("Codex", 50) + 16, 80, "重置记录", 50, "#38d6ee")
    brand = "YanyuBot"
    text(1122 - measure(brand, 28, True), 80, brand, 28, "#c1cad8", True)
    draw.rounded_rectangle((44, 120, 1156, height - 44), radius=28, fill="#090d15", outline="#1b2636", width=2)
    text(78, 184, f"{now.year} 年 {now.month} 月", 34)
    number = str(total)
    x = 1122 - measure("次重置", 28, False) - 18 - measure(number, 52)
    text(x, 188, number, 52)
    text(x + measure(number, 52) + 18, 184, "次重置", 28, "#9ba9bd", False)
    text(78, 245, "日期", 24, "#9ba9bd", False)
    text(495, 245, "时间", 24, "#9ba9bd", False)
    text(1122 - measure("重置类型", 24, False), 245, "重置类型", 24, "#9ba9bd", False)
    draw.line((78, 267, 1122, 267), fill="#1b2636", width=2)
    if not rows:
        text(78, 317, "本月暂无重置记录", 32, "#9ba9bd", False)
    for index, (date, record) in enumerate(rows):
        baseline = 317 + index * 66
        text(78, baseline, date.strftime("%m-%d"))
        draw.text((495, baseline), date.strftime("%H:%M"), font=time_font, fill="#c1cad8", anchor="ls")
        banked = record.get("reset_type") == "banked"
        label, color = ("储备", "#a78bfa") if banked else ("普通", "#38d6ee")
        text(1122 - measure(label, 28), baseline, label, 28, color)
        if index < len(rows) - 1:
            draw.line((78, baseline + 22, 1122, baseline + 22), fill="#151e2d", width=1)
    if pages > 1:
        value = f"{page} / {pages}"
        text(1122 - measure(value, 24, False), height - 16, value, 24, "#9ba9bd", False)
    result = io.BytesIO()
    image.convert("RGB").save(result, "PNG", optimize=True)
    result.name = f"codex-resets-{now:%Y-%m}-{page}.png"
    result.seek(0)
    return result


def requested_month(message, now):
    value = getattr(message, "arguments", None)
    if not isinstance(value, str):
        values = getattr(message, "parameter", None)
        if values is not None:
            value = values if isinstance(values, str) else " ".join(str(item) for item in values)
        else:
            text = getattr(message, "text", None) or ""
            match = re.fullmatch(r"[,，/]cz(?:\s+(.*))?", text.strip(), re.I)
            value = (match[1] or "") if match else ""
    value = value.strip()
    if not value:
        return None
    if not re.fullmatch(r"[1-9]|1[0-2]", value):
        raise ValueError("月份请填写 1–12，例如 ,cz 10。直接发送 ,cz 查询有记录的最新月份。")
    return int(value)


def month_range(now, month, year=None):
    start = now.replace(year=now.year if year is None else year, month=month, day=1, hour=0, minute=0, second=0, microsecond=0)
    end = start.replace(year=start.year + 1, month=1) if month == 12 else start.replace(month=month + 1)
    return start, min(end, now)


async def latest_record_month(now):
    params = {"limit": 1, "order": "desc", "from": "1970-01-01T00:00:00Z", "to": iso_utc(now)}
    payload = await asyncio.to_thread(request_json, f"{API_URL}?{urlencode(params)}")
    records = payload.get("data")
    if not isinstance(records, list):
        raise RuntimeError("接口没有返回最新月份信息。")
    if not records:
        return now.year, now.month
    first = records[0]
    date = parse_announcement_time(first.get("announced_at")) if isinstance(first, dict) else None
    if date is None or date > now:
        raise RuntimeError("最新记录的时间无效，请稍后重试。")
    return date.year, date.month


async def send_month_result(client, message, records, month_start, cutoff):
    rows = []
    seen = set()
    for record in records:
        if not isinstance(record, dict):
            continue
        date = parse_announcement_time(record.get("announced_at"))
        if date is None or date > cutoff or (date.year, date.month) != (month_start.year, month_start.month):
            continue
        identity = record.get("id")
        if identity and str(identity) in seen:
            continue
        if identity:
            seen.add(str(identity))
        rows.append((date, record))
    rows.sort(key=lambda row: row[0], reverse=True)
    chunks = [rows[i:i + ROWS_PER_IMAGE] for i in range(0, len(rows), ROWS_PER_IMAGE)] or [[]]
    options = {"chat_id": message.chat.id, "parse_mode": ParseMode.HTML}
    reply_id = getattr(message, "reply_to_message_id", None) or getattr(message, "reply_to_msg_id", None)
    if reply_id:
        options["reply_to_message_id"] = reply_id
    for index, page_rows in enumerate(chunks, 1):
        image = None
        try:
            image = await asyncio.to_thread(create_month_card, page_rows, month_start, len(rows), index, len(chunks))
            await client.send_photo(photo=image, **options)
        finally:
            if image is not None:
                image.close()
    with contextlib.suppress(Exception):
        await message.delete()


@listener(
    is_plugin=True,
    outgoing=True,
    command="cz",
    description="图片查询 Codex 重置记录，默认最新有记录的月份，可指定今年月份。",
    parameters="[月份 1–12]",
)
async def codex_reset_history(client: Client, message: Message) -> None:
    now = datetime.now(TIME_ZONE)
    try:
        month = requested_month(message, now)
        year = now.year
        if month is None:
            year, month = await latest_record_month(now)
        start, end = month_range(now, month, year)
        records = await fetch_resets(start, end) if start <= end else []
        await send_month_result(client, message, records, start, end)
    except Exception as exc:
        await message.edit(
            f"查询失败：{html.escape(str(exc))}",
            parse_mode=ParseMode.HTML,
        )
